    const rooms=_Ba?._cm?._u3t?.ins;
// [VI dòng gốc 2231] Khai báo biến không gán lại bằng const: ui = đọc _ft?._Y4n?.ins nếu đối tượng tồn tại (bỏ qua truy cập/gọi khi phần tùy chọn không tồn tại)
    const ui=_ft?._Y4n?.ins;
// [VI dòng gốc 2232] Kiểm tra !m || !rpc || !party || !rooms || !ui: đúng thì chạy nhánh sau if. | Kết thúc hàm hiện tại và trả về: null.
    if (!m || !rpc || !party || !rooms || !ui) return null;
// [VI dòng gốc 2233] Khai báo biến không gán lại bằng const: pane = nếu ui.isOpened?.(1291) thì lấy ui.getPanelById?.(1291), ngược lại lấy null
    const pane=ui.isOpened?.(1291) ? ui.getPanelById?.(1291) : null;
// [VI dòng gốc 2234] Khai báo biến không gán lại bằng const: raw = gọi Number(pane?._Qh) để chuyển sang số
    const raw=Number(pane?._Qh);
