    const m = boss(), cfgs = _ft?._pat?.ins?.cfgs, role = _Ba?._rJ?._O$?.ins;
// [VI dòng gốc 2444] Khai báo biến không gán lại bằng const: n = đọc m?.getBsTimesBySceneType?.(4)?.[2] nếu đối tượng tồn tại (bỏ qua truy cập/gọi khi phần tùy chọn không tồn tại)
    const n = m?.getBsTimesBySceneType?.(4)?.[2];
