    const m = _Ba?._Fvt?._Evt?.inst, cf = _ft?._TZ?.ins;
// [VI dòng gốc 2454] Kiểm tra !m || typeof m.getMaxCCEnter !== 'function' || !cf: đúng thì chạy nhánh sau if. | Kết thúc hàm hiện tại và trả về: null.
    if (!m || typeof m.getMaxCCEnter !== 'function' || !cf) return null;
// [VI dòng gốc 2455] Khai báo biến không gán lại bằng const: grade = gọi m.getMaxCCEnter()
    const grade = m.getMaxCCEnter();
