      if (t-j.at>20000) return finish(false,'Mở Tinh Thần quá giờ',8000);
// [VI dòng gốc 2662] Khai báo biến không gán lại bằng const: p = nếu r.ui.isOpened?.(605) thì lấy r.ui.getPanelById?.(605), ngược lại lấy null
      const p=r.ui.isOpened?.(605)?r.ui.getPanelById?.(605):null;
// [VI dòng gốc 2663] Kiểm tra !p || p.destroyed || !p.parent: đúng thì chạy nhánh sau if. | Kết thúc hàm hiện tại mà không trả giá trị cụ thể.
      if (!p || p.destroyed || !p.parent) return;
