      const id=Number(r?.[0]),result=Number(r?.[1]);
// [VI dòng gốc 2792] Khai báo biến không gán lại bằng const: kind = gọi Number(r?.[3]?.[0]) để chuyển sang số
      const kind=Number(r?.[3]?.[0]);
