      if (!Array.isArray(materials) || materials.length<1 ||
// [VI dòng gốc 2801] Bỏ phần còn lại của vòng hiện tại và chuyển sang vòng tiếp theo.
          materials.length>4) continue;
// [VI dòng gốc 2802] Khai báo biến có thể gán lại bằng let: possible = Infinity; good = true
      let possible=Infinity,good=true;
// [VI dòng gốc 2803] Khai báo biến không gán lại bằng const: uidList = tạo mảng gồm 0 vị trí: []; matIds = tạo mảng gồm 0 vị trí: []
      const uidList=[],matIds=[];
