  const red=id=>{try{return _Ba?._Xo?._Ko?.instance?.getRpKeyState?.(id)===true;}catch(_){return false;}};
// [VI dòng gốc 5187] Khai báo biến không gán lại bằng const: online = tạo hàm với tham số (không có); mỗi lần gọi trả về đọc _Ba?._s6t?._e6t?.ins nếu đối tượng tồn tại (bỏ qua truy cập/gọi khi phần tùy chọn không tồn tại)
  const online=()=>_Ba?._s6t?._e6t?.ins;
// [VI dòng gốc 5188] Khai báo biến không gán lại bằng const: sale = tạo hàm với tham số (không có); mỗi lần gọi trả về đọc _Ba?._af?._qwt?.instance nếu đối tượng tồn tại (bỏ qua truy cập/gọi khi phần tùy chọn không tồn tại)
  const sale=()=>_Ba?._af?._qwt?.instance;
// [VI dòng gốc 5189] Khai báo biến không gán lại bằng const: saleRpc = tạo hàm với tham số (không có); mỗi lần gọi trả về đọc _Ba?._af?._hf?.instance nếu đối tượng tồn tại (bỏ qua truy cập/gọi khi phần tùy chọn không tồn tại)
  const saleRpc=()=>_Ba?._af?._hf?.instance;
// [VI dòng gốc 5190] Khai báo biến không gán lại bằng const: id = tạo hàm với tham số n; mỗi lần gọi trả về nếu Number.isSafeInteger(Number(n))&&Number(n)>0 thì lấy Number(n), ngược lại lấy 0
  const id=n=>Number.isSafeInteger(Number(n))&&Number(n)>0?Number(n):0;
// [VI dòng gốc 5191] Định nghĩa hàm onlineProbe; tham số: không có
  function onlineProbe(){
// [VI dòng gốc 5192] Kiểm tra !C.online||!red(259): đúng thì chạy nhánh sau if. | Kết thúc hàm hiện tại và trả về: tạo đối tượng gồm ready, signature.
    if(!C.online||!red(259))return {ready:false,signature:'off'};
// [VI dòng gốc 5193] Khai báo biến không gán lại bằng const: rows = đọc online()?.updateRewardReply nếu đối tượng tồn tại (bỏ qua truy cập/gọi khi phần tùy chọn không tồn tại)
    const rows=online()?.updateRewardReply;
// [VI dòng gốc 5194] Kiểm tra !Array.isArray(rows): đúng thì chạy nhánh sau if. | Kết thúc hàm hiện tại và trả về: tạo đối tượng gồm ready, signature.
    if(!Array.isArray(rows))return {ready:false,signature:'no-data'};
// [VI dòng gốc 5195] Khai báo biến không gán lại bằng const: data = gọi rows.filter(x=>Array.isArray(x)&&id(x[0])) để giữ phần tử thỏa điều kiện
    const data=rows.filter(x=>Array.isArray(x)&&id(x[0]));
// [VI dòng gốc 5196] Khai báo biến không gán lại bằng const: ready = gọi data.find(x=>Number(x[1])===1) để tìm phần tử đầu tiên thỏa điều kiện
    const ready=data.find(x=>Number(x[1])===1);
// [VI dòng gốc 5197] Kết thúc hàm hiện tại và trả về: tạo đối tượng gồm ready, id, signature, count.
    return {ready:!!ready,id:ready?id(ready[0]):0,
// [VI dòng gốc 5198] Thuộc tính signature: gọi JSON.stringify(data.map(x=>[id(x[0]),Number(x[1])])) để chuyển giá trị thành chuỗi JSON
      signature:JSON.stringify(data.map(x=>[id(x[0]),Number(x[1])])),
// [VI dòng gốc 5199] Thuộc tính count: đọc data.filter(x=>Number(x[1])===1).length
      count:data.filter(x=>Number(x[1])===1).length};
// [VI dòng gốc 5200] Đóng khối/hàm/mảng/lời gọi đã mở; dấu phẩy hoặc chấm phẩy kết thúc phần tương ứng.
  }
