    const open=!!j&&goodInt(id)&&j.isOpened?.(id)===true;
// [VI dòng gốc 5808] Khai báo biến không gán lại bằng const: ui = nếu open thì lấy j.getPanelById?.(id)||j.getDialogById?.(id)||null, ngược lại lấy null
