    const current=Array.isArray(opps)&&Array.isArray(opps[3])?opps[3]:null;
// [VI dòng gốc 6082] Khai báo biến không gán lại bằng const: myRank = gọi num(current?.[4])
    const myRank=num(current?.[4]);
