    const cd=Number.isFinite(until)&&until>timeSV();
// [VI dòng gốc 6093] Khai báo biến không gán lại bằng const: quick = đảo giá trị đúng/sai của !(C.allowQuick&&Array.isArray(t)&&t[5]===true|| C.allowQuick&&Array.isArray(t)&&t[5]===1)
    const quick=!!(C.allowQuick&&Array.isArray(t)&&t[5]===true||
// [VI dòng gốc 6094] gọi Array.isArray(t)
      C.allowQuick&&Array.isArray(t)&&t[5]===1);
