    const sig=JSON.stringify([q?.id,q?.state,q?.progress,Array.isArray(t)?t.slice(0,6):null,
// [VI dòng gốc 6098] Định nghĩa hàm hàm không đặt tên; tham số: p
      current?.[4],candidates.map(p=>[p.id,p.power,p.rank])]);
