    if(q?.id!==S.questId){S.questId=q?.id??'';S.lastSig='';S.lastRequestAt=0;S.attempts.clear();}
// [VI dòng gốc 6102] Khai báo biến không gán lại bằng const: questCount = S.quests.get(q?.id) hoặc dùng vế phải khi vế trái là null/undefined: 0
    const questCount=S.quests.get(q?.id)??0;
