// [VI dòng gốc 6623] Định nghĩa hàm listEra; tham số: không có
  function listEra(){
// [VI dòng gốc 6624] Khai báo biến không gán lại bằng const: m = gọi era(); raw = đọc m?.ids nếu đối tượng tồn tại (bỏ qua truy cập/gọi khi phần tùy chọn không tồn tại)
    const m=era(),raw=m?.ids;
// [VI dòng gốc 6625] Kiểm tra !Array.isArray(raw)||!raw.length: đúng thì chạy nhánh sau if. | Kết thúc hàm hiện tại và trả về: tạo mảng gồm 0 vị trí: [].
    if(!Array.isArray(raw)||!raw.length)return [];
// [VI dòng gốc 6626] Khai báo biến không gán lại bằng const: out = tạo mảng gồm 0 vị trí: []
    const out=[];
// [VI dòng gốc 6627] Duyệt từng giá trị trong [...new Set(raw)].filter(validId) bằng const id. | Khai báo biến không gán lại bằng const: id (chưa gán giá trị)
    for(const id of [...new Set(raw)].filter(validId)){
// [VI dòng gốc 6628] Khai báo biến không gán lại bằng const: n = gọi m?.getEraNode(id) (bỏ qua truy cập/gọi khi phần tùy chọn không tồn tại)
      const n=m?.getEraNode?.(id);
// [VI dòng gốc 6629] Khai báo biến không gán lại bằng const: c = gọi eraCfg()?.getCfgById(id) để tra cấu hình theo ID bằng API client (bỏ qua truy cập/gọi khi phần tùy chọn không tồn tại)
      const c=eraCfg()?.getCfgById?.(id);
// [VI dòng gốc 6630] Khai báo biến không gán lại bằng const: arr = nếu Array.isArray(c?.[2]) thì lấy c[2], ngược lại lấy []
      const arr=Array.isArray(c?.[2])?c[2]:[];
// [VI dòng gốc 6631] Khai báo biến không gán lại bằng const: state = nếu Array.isArray(n) thì lấy Number(n[1]), ngược lại lấy null
      const state=Array.isArray(n)?Number(n[1]):null;
// [VI dòng gốc 6632] gọi out.push({id:Number(id),state:Number.isInteger(state)?state:null, status:state===0?'CHUA XONG':state===1?'CO THE NHAN':state===2?…) để thêm phần tử vào cuối mảng
      out.push({id:Number(id),state:Number.isInteger(state)?state:null,
// [VI dòng gốc 6633] Thuộc tính status: nếu state===0 thì lấy 'CHUA XONG', ngược lại lấy state===1?'CO THE NHAN':state===2?'DA NHAN':'CHUA DONG BO'
        status:state===0?'CHUA XONG':state===1?'CO THE NHAN':state===2?'DA NHAN':'CHUA DONG BO',
// [VI dòng gốc 6634] Thuộc tính progress: nếu Array.isArray(n) thì lấy Number(n[2]??0), ngược lại lấy null
        progress: Array.isArray(n)?Number(n[2]??0):null,
// [VI dòng gốc 6635] Thuộc tính target: nếu Number.isFinite(Number(arr[1])) thì lấy Number(arr[1]), ngược lại lấy null
        target:Number.isFinite(Number(arr[1]))?Number(arr[1]):null,
// [VI dòng gốc 6636] Thuộc tính name: gọi String(c?.[1]??'Nhiem vu #'+id) để chuyển sang chuỗi
        name:String(c?.[1]??'Nhiem vu #'+id),
// [VI dòng gốc 6637] Thuộc tính actionId: nếu Number.isInteger(Number(arr[2])) thì lấy Number(arr[2]), ngược lại lấy -1
        actionId:Number.isInteger(Number(arr[2]))?Number(arr[2]):-1,
// [VI dòng gốc 6638] Thuộc tính actionMode: gọi Number(arr[0]) để chuyển sang số | Thuộc tính hasConfig: đảo giá trị đúng/sai của !c
        actionMode:Number(arr[0]),hasConfig:!!c});
// [VI dòng gốc 6639] Đóng khối/hàm/mảng/lời gọi đã mở; dấu phẩy hoặc chấm phẩy kết thúc phần tương ứng.
    }
// [VI dòng gốc 6640] Kết thúc hàm hiện tại và trả về: out.
    return out;
// [VI dòng gốc 6641] Đóng khối/hàm/mảng/lời gọi đã mở; dấu phẩy hoặc chấm phẩy kết thúc phần tương ứng.
  }
