  const now=()=>Date.now();
// [VI dòng gốc 7978] Khai báo biến không gán lại bằng const: normalize = tạo hàm với tham số x; mỗi lần gọi trả về gọi String(x??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'') .replace(/[đĐ]/g,'d').toLowerCase()
  const normalize=x=>String(x??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'')
