const safe=()=>_Ba?._$a?.SceneUtil?.isCommonScene===true&&
// [VI dòng gốc 8845] Tiếp tục hàm safe; thành phần cú pháp bắt đầu bằng name. Đọc cùng dòng mở phía trên: _Ba?._$a?._yo?.ins?.isInMission!==true&&_Ba?._$a?._yo?.ins?.isInArena!==true;
  _Ba?._$a?._yo?.ins?.isInMission!==true&&_Ba?._$a?._yo?.ins?.isInArena!==true;
// [VI dòng gốc 8846] Định nghĩa hàm rule; tham số: task
function rule(task){
// [VI dòng gốc 8847] Kiểm tra !task||Number(task.actionId)!==18: đúng thì chạy nhánh sau if. | Kết thúc hàm hiện tại và trả về: null.
  if(!task||Number(task.actionId)!==18)return null;
// [VI dòng gốc 8848] Khai báo biến không gán lại bằng const: n = gọi norm(task.name)
  const n=norm(task.name);
// [VI dòng gốc 8849] Kiểm tra !/da hon/.test(n): đúng thì chạy nhánh sau if. | Kết thúc hàm hiện tại và trả về: null.
  if(!/da hon/.test(n))return null;
// [VI dòng gốc 8850] Khai báo biến không gán lại bằng const: total = gọi /(?:tong cap|tong lv|tong level).*?da hon.*?(?:lv\.?|level|cap)\s*(\d{1,5})\b/.exec(n)
  const total=/(?:tong cap|tong lv|tong level).*?da hon.*?(?:lv\.?|level|cap)\s*(\d{1,5})\b/.exec(n);
// [VI dòng gốc 8851] Kiểm tra total: đúng thì chạy nhánh sau if. | Kết thúc hàm hiện tại và trả về: tạo đối tượng gồm mode, target.
  if(total)return {mode:'total',target:Number(total[1])};
// [VI dòng gốc 8852] Kết thúc hàm hiện tại và trả về: null.
  return null;
// [VI dòng gốc 8853] Đóng khối/hàm/mảng/lời gọi đã mở; dấu phẩy hoặc chấm phẩy kết thúc phần tương ứng.
}
// [VI dòng gốc 8854] Định nghĩa hàm stone; tham số: itemId
function stone(itemId){
// [VI dòng gốc 8855] Kiểm tra !Number.isSafeInteger(Number(itemId))||Number(itemId)<=0: đúng thì chạy nhánh sau if. | Kết thúc hàm hiện tại và trả về: null.
  if(!Number.isSafeInteger(Number(itemId))||Number(itemId)<=0)return null;
// [VI dòng gốc 8856] Khai báo biến không gán lại bằng const: row = gọi cfg()?.getCfgById(Number(itemId)) để tra cấu hình theo ID bằng API client (bỏ qua truy cập/gọi khi phần tùy chọn không tồn tại)
  const row=cfg()?.getCfgById?.(Number(itemId));
// [VI dòng gốc 8857] Khai báo biến không gán lại bằng const: level = gọi Number(row?.[5]) để chuyển sang số; kind = gọi Number(row?.[3]) để chuyển sang số; need = gọi Number(row?.[6]) để chuyển sang số
  const level=Number(row?.[5]),kind=Number(row?.[3]),need=Number(row?.[6]);
// [VI dòng gốc 8858] Kết thúc hàm hiện tại và trả về: nếu row&&Number.isFinite(level)&&level>=0 thì lấy {id:Number(itemId),level,kind,need}, ngược lại lấy null.
  return row&&Number.isFinite(level)&&level>=0?{id:Number(itemId),level,kind,need}:null;
// [VI dòng gốc 8859] Đóng khối/hàm/mảng/lời gọi đã mở; dấu phẩy hoặc chấm phẩy kết thúc phần tương ứng.
}
// [VI dòng gốc 8860] Định nghĩa hàm owned; tham số: id. Mục đích: kiểm tra đúng nhân vật và phiên còn được phép chạy | Khai báo biến có thể gán lại bằng let: n = 0 | Bắt đầu khối try; lỗi phát sinh sẽ được xử lý ở catch hoặc chuyển ra ngoài. | gán n bằng Number(bag()?.getItemCountById?.(id))
function owned(id){let n=0;try{n=Number(bag()?.getItemCountById?.(id));}catch(_){window.KVPV_V1?.diagnostics?.record(_);}
// [VI dòng gốc 8861] Kết thúc hàm hiện tại và trả về: nếu Number.isFinite(n)&&n>=0 thì lấy n, ngược lại lấy 0.
  return Number.isFinite(n)&&n>=0?n:0;
// [VI dòng gốc 8862] Đóng khối/hàm/mảng/lời gọi đã mở; dấu phẩy hoặc chấm phẩy kết thúc phần tương ứng.
}
// [VI dòng gốc 8863] Định nghĩa hàm slots; tham số: không có
function slots(){
// [VI dòng gốc 8864] Khai báo biến không gán lại bằng const: m = gọi model(); d = gọi m?.getValueByPos() (bỏ qua truy cập/gọi khi phần tùy chọn không tồn tại); pos = gọi m?.getHavePos() (bỏ qua truy cập/gọi khi phần tùy chọn không tồn tại)
  const m=model(),d=m?.getValueByPos?.(),pos=m?.getHavePos?.();
// [VI dòng gốc 8865] Kiểm tra !d||typeof d.get!=='function'||!Array.isArray(pos): đúng thì chạy nhánh sau if. | Kết thúc hàm hiện tại và trả về: null.
  if(!d||typeof d.get!=='function'||!Array.isArray(pos))return null;
// [VI dòng gốc 8866] Khai báo biến không gán lại bằng const: records = tạo mảng gồm 0 vị trí: []; parts = tạo mảng gồm 1 vị trí: [...new Set(pos.map(Number).filter(x=>Number.isInteger(x)&&x>0))]
  const records=[],parts=[...new Set(pos.map(Number).filter(x=>Number.isInteger(x)&&x>0))];
// [VI dòng gốc 8867] Duyệt từng giá trị trong parts bằng const part. | Khai báo biến không gán lại bằng const: part (chưa gán giá trị) | Lặp for: khởi tạo let k=0; tiếp tục khi k<5; sau mỗi vòng k++. | Khai báo biến có thể gán lại bằng let: k = 0
  for(const part of parts)for(let k=0;k<5;k++){
// [VI dòng gốc 8868] Khai báo biến không gán lại bằng const: key = tính biểu thức 10*part+k; id = gọi d.get(key); entry = nếu id===null||id===undefined thì lấy null, ngược lại lấy stone(Number(id))
    const key=10*part+k,id=d.get(key),entry=id===null||id===undefined?null:stone(Number(id));
// [VI dòng gốc 8869] Kiểm tra id!==null&&id!==undefined&&!entry: đúng thì chạy nhánh sau if. | Kết thúc hàm hiện tại và trả về: null.
    if(id!==null&&id!==undefined&&!entry)return null; // do not trust incomplete cfg
// [VI dòng gốc 8870] gọi records.push({part,slot:k,id:entry?.id||0,level:entry?.level||0,kind:entry?.kind||k, need:entry?.need||0}) để thêm phần tử vào cuối mảng
    records.push({part,slot:k,id:entry?.id||0,level:entry?.level||0,kind:entry?.kind||k,
// [VI dòng gốc 8871] Thuộc tính need: entry?.need hoặc dùng vế phải khi vế trái falsy: 0
      need:entry?.need||0});
// [VI dòng gốc 8872] Đóng khối/hàm/mảng/lời gọi đã mở; dấu phẩy hoặc chấm phẩy kết thúc phần tương ứng.
  }
// [VI dòng gốc 8873] Kết thúc hàm hiện tại và trả về: records.
  return records;
// [VI dòng gốc 8874] Đóng khối/hàm/mảng/lời gọi đã mở; dấu phẩy hoặc chấm phẩy kết thúc phần tương ứng.
}
// [VI dòng gốc 8875] Định nghĩa hàm bagByType; tham số: kind
function bagByType(kind){
// [VI dòng gốc 8876] Bắt đầu khối try; lỗi phát sinh sẽ được xử lý ở catch hoặc chuyển ra ngoài. | Kết thúc hàm hiện tại và trả về: gọi (model()?.getStByType?.(kind)||[]).filter(a=>Array.isArray(a)&&stone(Number(a[0]))&&Number(a[1])>0) để giữ phần tử thỏa điều kiện. | Nhận lỗi bằng _ và chạy phần xử lý lỗi. | Kết thúc hàm hiện tại và trả về: tạo mảng gồm 0 vị trí: [].
  try{return (model()?.getStByType?.(kind)||[]).filter(a=>Array.isArray(a)&&stone(Number(a[0]))&&Number(a[1])>0);}catch(_){return [];}
// [VI dòng gốc 8877] Đóng khối/hàm/mảng/lời gọi đã mở; dấu phẩy hoặc chấm phẩy kết thúc phần tương ứng.
}
// [VI dòng gốc 8878] Định nghĩa hàm actionFor; tham số: records
function actionFor(records){
// [VI dòng gốc 8879] Khai báo biến không gán lại bằng const: m = gọi model(); actions = tạo mảng gồm 0 vị trí: []
  const m=model(),actions=[];
// [VI dòng gốc 8880] Kiểm tra !records: đúng thì chạy nhánh sau if. | Kết thúc hàm hiện tại và trả về: actions.
  if(!records)return actions;
// [VI dòng gốc 8881] Khai báo biến không gán lại bằng const: vip = tính biểu thức m?.vipIsOpen===true
  const vip=m?.vipIsOpen===true;
// [VI dòng gốc 8882] Khai báo biến không gán lại bằng const: byPart = tạo đối tượng bằng Map()
  const byPart=new Map();
// [VI dòng gốc 8883] Duyệt từng giá trị trong records bằng const r. | Khai báo biến không gán lại bằng const: r (chưa gán giá trị) | Kiểm tra !byPart.has(r.part): đúng thì chạy nhánh sau if. | gọi byPart.set(r.part, [])
  for(const r of records){if(!byPart.has(r.part))byPart.set(r.part,[]);byPart.get(r.part).push(r);}
// [VI dòng gốc 8884] Duyệt từng giá trị trong byPart bằng const [part,ss]. | Khai báo biến không gán lại bằng const: [part,ss] (chưa gán giá trị)
  for(const [part,ss] of byPart){
// [VI dòng gốc 8885] Chú thích gốc của tác giả; không được thực thi. Nội dung: Match P_SoulStoneView._rEn precedence per part: insert / replace / level-up.
    // Match P_SoulStoneView._rEn precedence per part: insert / replace / level-up.
// [VI dòng gốc 8886] Khai báo biến có thể gán lại bằng let: candidate = null
    let candidate=null;
// [VI dòng gốc 8887] Duyệt từng giá trị trong ss bằng const s. | Khai báo biến không gán lại bằng const: s (chưa gán giá trị)
    for(const s of ss){
// [VI dòng gốc 8888] Kiểm tra s.slot===0&&!vip: đúng thì chạy nhánh sau if. | Bỏ phần còn lại của vòng hiện tại và chuyển sang vòng tiếp theo.
      if(s.slot===0&&!vip)continue; // VIP-only socket, cannot unlock by auto
// [VI dòng gốc 8889] Kiểm tra s.id===0&&C.allowInlay: đúng thì chạy nhánh sau if.
      if(s.id===0&&C.allowInlay){
// [VI dòng gốc 8890] Khai báo biến không gán lại bằng const: kind = nếu s.slot===0 thì lấy null, ngược lại lấy s.slot
        const kind=s.slot===0?null:s.slot;
// [VI dòng gốc 8891] Khai báo biến có thể gán lại bằng let: list = nếu kind===null thì lấy [], ngược lại lấy bagByType(kind)
        let list=kind===null?[]:bagByType(kind);
// [VI dòng gốc 8892] Kiểm tra s.slot===0: đúng thì chạy nhánh sau if. | Bắt đầu khối try; lỗi phát sinh sẽ được xử lý ở catch hoặc chuyển ra ngoài. | gán list bằng (bag()?.getItemsByBagType?.(2)||[]).filter(a=>Array.isArray(a)&&stone(Number(a[0]))&&Number(a[1])>0) | Nhận lỗi bằng _ và chạy phần xử lý lỗi.
        if(s.slot===0){try{list=(bag()?.getItemsByBagType?.(2)||[]).filter(a=>Array.isArray(a)&&stone(Number(a[0]))&&Number(a[1])>0);}catch(_){window.KVPV_V1?.diagnostics?.record(_);}}
// [VI dòng gốc 8893] Kiểm tra list.length: đúng thì chạy nhánh sau if. | gán candidate bằng {part,mode:0,reason:'inlay',slot:s.slot,gain:Math.max(...list.map(a=>stone(Number(a[0]))?.level||0))} | Thoát vòng lặp/switch hiện tại.
        if(list.length){candidate={part,mode:0,reason:'inlay',slot:s.slot,gain:Math.max(...list.map(a=>stone(Number(a[0]))?.level||0))};break;}
// [VI dòng gốc 8894] Đóng khối/hàm/mảng/lời gọi đã mở; dấu phẩy hoặc chấm phẩy kết thúc phần tương ứng.
      }
// [VI dòng gốc 8895] Kiểm tra s.id: đúng thì chạy nhánh sau if.
      if(s.id){
// [VI dòng gốc 8896] Kiểm tra C.allowReplace: đúng thì chạy nhánh sau if.
        if(C.allowReplace){
// [VI dòng gốc 8897] Khai báo biến không gán lại bằng const: better = gọi bagByType(s.kind).map(a=>stone(Number(a[0]))).filter(v=>v&&v.level>s.level) để giữ phần tử thỏa điều kiện
          const better=bagByType(s.kind).map(a=>stone(Number(a[0]))).filter(v=>v&&v.level>s.level);
// [VI dòng gốc 8898] Kiểm tra better.length: đúng thì chạy nhánh sau if. | gán candidate bằng {part,mode:1,reason:'replace',slot:s.slot,gain:Math.max(...better.map(v=>v.level))-s.level} | Thoát vòng lặp/switch hiện tại.
          if(better.length){candidate={part,mode:1,reason:'replace',slot:s.slot,gain:Math.max(...better.map(v=>v.level))-s.level};break;}
// [VI dòng gốc 8899] Đóng khối/hàm/mảng/lời gọi đã mở; dấu phẩy hoặc chấm phẩy kết thúc phần tương ứng.
        }
// [VI dòng gốc 8900] Kiểm tra C.allowUpgrade: đúng thì chạy nhánh sau if.
        if(C.allowUpgrade){
// [VI dòng gốc 8901] Khai báo biến không gán lại bằng const: st = gọi stone(s.id); cap = gọi Number(cfg()?.stoneMaxLv) để chuyển sang số
          const st=stone(s.id),cap=Number(cfg()?.stoneMaxLv);
// [VI dòng gốc 8902] Kiểm tra st&&Number.isFinite(st.need)&&st.need>=2&&owned(st.id)+1>=st.need&& (!Number.isFinite(cap)||st.level<cap): đúng thì chạy nhánh sau if.
          if(st&&Number.isFinite(st.need)&&st.need>=2&&owned(st.id)+1>=st.need&&
// [VI dòng gốc 8903] gọi Number.isFinite(cap)
            (!Number.isFinite(cap)||st.level<cap)){
// [VI dòng gốc 8904] gán candidate bằng {part,mode:2,reason:'upgrade',slot:s.slot,gain:1} | Thoát vòng lặp/switch hiện tại.
            candidate={part,mode:2,reason:'upgrade',slot:s.slot,gain:1};break;
// [VI dòng gốc 8905] Đóng khối/hàm/mảng/lời gọi đã mở; dấu phẩy hoặc chấm phẩy kết thúc phần tương ứng.
          }
// [VI dòng gốc 8906] Đóng khối/hàm/mảng/lời gọi đã mở; dấu phẩy hoặc chấm phẩy kết thúc phần tương ứng.
        }
// [VI dòng gốc 8907] Đóng khối/hàm/mảng/lời gọi đã mở; dấu phẩy hoặc chấm phẩy kết thúc phần tương ứng.
      }
// [VI dòng gốc 8908] Đóng khối/hàm/mảng/lời gọi đã mở; dấu phẩy hoặc chấm phẩy kết thúc phần tương ứng.
    }
// [VI dòng gốc 8909] Kiểm tra candidate: đúng thì chạy nhánh sau if. | gọi actions.push(candidate) để thêm phần tử vào cuối mảng
    if(candidate)actions.push(candidate);
// [VI dòng gốc 8910] Đóng khối/hàm/mảng/lời gọi đã mở; dấu phẩy hoặc chấm phẩy kết thúc phần tương ứng.
  }
// [VI dòng gốc 8911] Kết thúc hàm hiện tại và trả về: gọi actions.sort((a,b)=>b.gain-a.gain||a.part-b.part) để sắp xếp mảng tại chỗ.
  return actions.sort((a,b)=>b.gain-a.gain||a.part-b.part);
// [VI dòng gốc 8912] Đóng khối/hàm/mảng/lời gọi đã mở; dấu phẩy hoặc chấm phẩy kết thúc phần tương ứng.
}
// [VI dòng gốc 8913] Định nghĩa hàm plan; tham số: task=q()
function plan(task=q()){
// [VI dòng gốc 8914] Khai báo biến không gán lại bằng const: pat = gọi rule(task); rs = gọi slots()
  const pat=rule(task),rs=slots();
// [VI dòng gốc 8915] Khai báo biến không gán lại bằng const: signature = gọi JSON.stringify([task?.id,task?.state,task?.progress, rs?.map(x=>[x.part,x.slot,x.id,x.level])]) để chuyển giá trị thành chuỗi JSON
  const signature=JSON.stringify([task?.id,task?.state,task?.progress,
// [VI dòng gốc 8916] Định nghĩa hàm hàm không đặt tên; tham số: x
    rs?.map(x=>[x.part,x.slot,x.id,x.level])]);
// [VI dòng gốc 8917] Khai báo biến không gán lại bằng const: sum = nếu rs thì lấy rs.reduce((n,x)=>n+x.level,0), ngược lại lấy null
  const sum=rs?rs.reduce((n,x)=>n+x.level,0):null;
// [VI dòng gốc 8918] Khai báo biến không gán lại bằng const: actions = nếu rs thì lấy actionFor(rs), ngược lại lấy []
  const actions=rs?actionFor(rs):[];
// [VI dòng gốc 8919] Khai báo biến không gán lại bằng const: chosen = actions[0] hoặc dùng vế phải khi vế trái falsy: null
  const chosen=actions[0]||null;
// [VI dòng gốc 8920] Khai báo biến không gán lại bằng const: spent = S.attempts.get(task?.id) hoặc dùng vế phải khi vế trái falsy: 0
  const spent=S.attempts.get(task?.id)||0;
// [VI dòng gốc 8921] Khai báo biến không gán lại bằng const: reached = pat&&sum!==null và chỉ đánh giá vế phải khi vế trái truthy: sum>=pat.target
  const reached=pat&&sum!==null&&sum>=pat.target;
// [VI dòng gốc 8922] Khai báo biến không gán lại bằng const: pending = !!S.pending&&S.pending.task===task?.id và chỉ đánh giá vế phải khi vế trái truthy: S.pending.sig===signature
  const pending=!!S.pending&&S.pending.task===task?.id&&S.pending.sig===signature;
// [VI dòng gốc 8923] Khai báo biến không gán lại bằng const: ready = !!pat&&C.enabled&&C.autoStone&&task?.state!==2&&rs!==null&&!reached&&!!chosen&& typeof rpc()?.oneKeyHandler==='function'&&spent<C.maxRequestsPerQuest&& now()-S.lastAt>=C.minGapMs&&… và chỉ đánh giá vế phải khi vế trái truthy: !C.requireCommonScene||safe()
  const ready=!!pat&&C.enabled&&C.autoStone&&task?.state!==2&&rs!==null&&!reached&&!!chosen&&
// [VI dòng gốc 8924] gọi rpc()
    typeof rpc()?.oneKeyHandler==='function'&&spent<C.maxRequestsPerQuest&&
// [VI dòng gốc 8925] gọi now() | gọi safe()
    now()-S.lastAt>=C.minGapMs&&!pending&&(!C.requireCommonScene||safe());
// [VI dòng gốc 8926] Khai báo biến không gán lại bằng const: reason = nếu !pat thì lấy 'Khong phai quest Tong cap Da Hon', ngược lại lấy task?.state===2?'Server quest da xong': rs===null?'Chua co du lieu da hon/trang bi':reached?'Da du tong cap, doi server': !chosen?'Chua co da de kham/thay/nang; khong mua them': ty…
  const reason=!pat?'Khong phai quest Tong cap Da Hon':task?.state===2?'Server quest da xong':
// [VI dòng gốc 8927] Tiếp tục hàm plan; thành phần cú pháp bắt đầu bằng name. Đọc cùng dòng mở phía trên: rs===null?'Chua co du lieu da hon/trang bi':reached?'Da du tong cap, doi server':
    rs===null?'Chua co du lieu da hon/trang bi':reached?'Da du tong cap, doi server':
// [VI dòng gốc 8928] Tiếp tục hàm plan; thành phần cú pháp bắt đầu bằng !/~. Đọc cùng dòng mở phía trên: !chosen?'Chua co da de kham/thay/nang; khong mua them':
    !chosen?'Chua co da de kham/thay/nang; khong mua them':
// [VI dòng gốc 8929] gọi rpc()
    typeof rpc()?.oneKeyHandler!=='function'?'Khong co nut native Da Hon':
// [VI dòng gốc 8930] Tiếp tục hàm plan; thành phần cú pháp bắt đầu bằng name. Đọc cùng dòng mở phía trên: spent>=C.maxRequestsPerQuest?'Vuot gioi han quest':pending?'Dang doi cap nhat server':
    spent>=C.maxRequestsPerQuest?'Vuot gioi han quest':pending?'Dang doi cap nhat server':
// [VI dòng gốc 8931] gọi safe()
    C.requireCommonScene&&!safe()?'Dang trong tran/phong':'San sang';
// [VI dòng gốc 8932] Kết thúc hàm hiện tại và trả về: tạo đối tượng gồm id, name, mode, target, total, ready, reason, choice, signature, spent, actions, pending.
  return {id:task?.id,name:task?.name,mode:pat?.mode||null,target:pat?.target||null,
// [VI dòng gốc 8933] Thuộc tính total: sum | Thuộc tính ready: dùng biến cùng tên | Thuộc tính reason: dùng biến cùng tên | Thuộc tính choice: chosen
    total:sum,ready,reason,choice:chosen,signature,spent,actions:actions.length,pending};
// [VI dòng gốc 8934] Đóng khối/hàm/mảng/lời gọi đã mở; dấu phẩy hoặc chấm phẩy kết thúc phần tương ứng.
}
// [VI dòng gốc 8935] Khai báo biến không gán lại bằng const: probe = tạo hàm với tham số task | Khai báo biến không gán lại bằng const: p = gọi plan(task) | Kết thúc hàm hiện tại và trả về: tạo đối tượng gồm ready, signature.
const probe=task=>{const p=plan(task);return {ready:p.ready,signature:p.signature};};
// [VI dòng gốc 8936] Định nghĩa hàm run; tham số: task, old
function run(task,old){
// [VI dòng gốc 8937] Chú thích gốc của tác giả; không được thực thi. Nội dung: The factory queue already owns the current work slot. Never check U.busy() here.
  // The factory queue already owns the current work slot. Never check U.busy() here.
// [VI dòng gốc 8938] Khai báo biến không gán lại bằng const: p = gọi plan(task)
  const p=plan(task);
// [VI dòng gốc 8939] Kiểm tra !p.ready||p.signature!==old.signature||q()?.id!==task?.id|| (C.requireCommonScene&&!safe())||typeof rpc()?.oneKeyHandler!=='function': đúng thì chạy nhánh sau if.
  if(!p.ready||p.signature!==old.signature||q()?.id!==task?.id||
// [VI dòng gốc 8940] gọi safe() | gọi rpc()
     (C.requireCommonScene&&!safe())||typeof rpc()?.oneKeyHandler!=='function')
// [VI dòng gốc 8941] Ném lỗi và chuyển luồng tới catch gần nhất: gọi Error('Stone snapshot changed, skip this attempt')
    throw Error('Stone snapshot changed, skip this attempt');
// [VI dòng gốc 8942] gán S.lastAt bằng now() | gọi S.attempts.set(task.id, (S.attempts.get(task.id)||0)+1)
  S.lastAt=now();S.attempts.set(task.id,(S.attempts.get(task.id)||0)+1);
// [VI dòng gốc 8943] Chú thích gốc của tác giả; không được thực thi. Nội dung: Set pending BEFORE RPC, preventing duplicate sends on synchronous callbacks.
  // Set pending BEFORE RPC, preventing duplicate sends on synchronous callbacks.
// [VI dòng gốc 8944] gán S.pending bằng {task:task.id,sig:p.signature,at:now(),total:p.total,choice:p.choice}
  S.pending={task:task.id,sig:p.signature,at:now(),total:p.total,choice:p.choice};
// [VI dòng gốc 8945] Bắt đầu khối try; lỗi phát sinh sẽ được xử lý ở catch hoặc chuyển ra ngoài. | gọi rpc().oneKeyHandler([p.choice.part,p.choice.mode]) | tăng S.sent một đơn vị sau khi lấy giá trị
  try{rpc().oneKeyHandler([p.choice.part,p.choice.mode]);S.sent++;}
// [VI dòng gốc 8946] Nhận lỗi bằng e và chạy phần xử lý lỗi. | tăng S.errors một đơn vị sau khi lấy giá trị | gán S.lastError bằng String(e) | Ném lỗi và chuyển luồng tới catch gần nhất: e
  catch(e){S.errors++;S.lastError=String(e);throw e;}
// [VI dòng gốc 8947] gọi console.log('[V8.6.19] DA GUI DA HON', {task:task.id,total:p.total,target:p.target,choice:p.choice})
  console.log('[V8.6.19] DA GUI DA HON',{task:task.id,total:p.total,target:p.target,choice:p.choice});
// [VI dòng gốc 8948] Đóng khối/hàm/mảng/lời gọi đã mở; dấu phẩy hoặc chấm phẩy kết thúc phần tương ứng.
}
// [VI dòng gốc 8949] Chú thích gốc của tác giả; không được thực thi. Nội dung: Thực hiện một lượt kiểm tra của module; các nhánh bên dưới quyết định có đủ điều kiện để hành động hay phải chờ.
// Thực hiện một lượt kiểm tra của module; các nhánh bên dưới quyết định có đủ điều kiện để hành động hay phải chờ.
// [VI dòng gốc 8950] Định nghĩa hàm tick; tham số: không có. Mục đích: xử lý một nhịp kiểm tra
function tick(){
// [VI dòng gốc 8951] Kiểm tra !C.enabled||!S.pending: đúng thì chạy nhánh sau if. | Kết thúc hàm hiện tại mà không trả giá trị cụ thể.
  if(!C.enabled||!S.pending)return;
// [VI dòng gốc 8952] Khai báo biến không gán lại bằng const: task = gọi q(); p = gọi plan(task)
  const task=q(),p=plan(task);
// [VI dòng gốc 8953] Kiểm tra task?.id!==S.pending.task||task?.state===2||p.signature!==S.pending.sig: đúng thì chạy nhánh sau if, sai thì chạy nhánh else.
  if(task?.id!==S.pending.task||task?.state===2||p.signature!==S.pending.sig){
// [VI dòng gốc 8954] tăng S.confirmed một đơn vị sau khi lấy giá trị | gọi S.history.push({at:new Date().toISOString(),id:S.pending.task,previous:S.pending.total,current:p.total}) để thêm phần tử vào cuối mảng
    S.confirmed++;S.history.push({at:new Date().toISOString(),id:S.pending.task,previous:S.pending.total,current:p.total});
// [VI dòng gốc 8955] gán S.pending bằng null
    S.pending=null;
// [VI dòng gốc 8956] Kiểm tra now()-S.pending.at>=C.ackTimeoutMs: đúng thì chạy nhánh sau if.
  }else if(now()-S.pending.at>=C.ackTimeoutMs){
// [VI dòng gốc 8957] gọi console.warn('[V8.6.19] Da Hon chua co ACK; khong gui lai cung trang thai')
    console.warn('[V8.6.19] Da Hon chua co ACK; khong gui lai cung trang thai');
// [VI dòng gốc 8958] gán S.pending bằng null
    S.pending=null; // factory maxAttemptsPerUnchangedState=1 remains the protection
// [VI dòng gốc 8959] Đóng khối/hàm/mảng/lời gọi đã mở; dấu phẩy hoặc chấm phẩy kết thúc phần tương ứng.
  }
// [VI dòng gốc 8960] Đóng khối/hàm/mảng/lời gọi đã mở; dấu phẩy hoặc chấm phẩy kết thúc phần tương ứng.
}
// [VI dòng gốc 8961] Chú thích gốc của tác giả; không được thực thi. Nội dung: Bật bộ điều khiển và lịch kiểm tra của module; trả trạng thái sau khi khởi động.
// Bật bộ điều khiển và lịch kiểm tra của module; trả trạng thái sau khi khởi động.
// [VI dòng gốc 8962] Định nghĩa hàm start; tham số: không có. Mục đích: khởi động bộ điều khiển | gán C.enabled bằng true | Kiểm tra F.config: đúng thì chạy nhánh sau if. | gán F.config.allowMaterialRecipes bằng true
function start(){C.enabled=true;if(F.config)F.config.allowMaterialRecipes=true;
// [VI dòng gốc 8963] Kiểm tra S.timer: đúng thì chạy nhánh sau if. | gọi __KVPV29.cancel(S.timer)
  if(S.timer)__KVPV29.cancel(S.timer);
// [VI dòng gốc 8964] gán S.timer bằng __KVPV29.every(()=>{try{tick();}catch(e){S.errors++;S.lastError=String(e);}},C.checkMs) | Bắt đầu khối try; lỗi phát sinh sẽ được xử lý ở catch hoặc chuyển ra ngoài. | gọi tick() để xử lý một nhịp kiểm tra | Nhận lỗi bằng e và chạy phần xử lý lỗi.
  S.timer=__KVPV29.every(()=>{try{tick();}catch(e){S.errors++;S.lastError=String(e);}},C.checkMs);
// [VI dòng gốc 8965] gọi tick() để xử lý một nhịp kiểm tra | Kết thúc hàm hiện tại và trả về: true.
  tick();return true;}
// [VI dòng gốc 8966] Chú thích gốc của tác giả; không được thực thi. Nội dung: Dừng bộ điều khiển, hủy lịch và giải phóng tài nguyên do module này sở hữu.
// Dừng bộ điều khiển, hủy lịch và giải phóng tài nguyên do module này sở hữu.
// [VI dòng gốc 8967] Định nghĩa hàm stop; tham số: không có. Mục đích: dừng bộ điều khiển và dọn tài nguyên | gán C.enabled bằng false | Kiểm tra S.timer: đúng thì chạy nhánh sau if. | gọi __KVPV29.cancel(S.timer)
function stop(){C.enabled=false;if(S.timer)__KVPV29.cancel(S.timer);S.timer=null;return true;}
// [VI dòng gốc 8968] Chú thích gốc của tác giả; không được thực thi. Nội dung: Trả trạng thái hiện tại để kiểm tra; ý nghĩa từng bộ đếm thuộc phạm vi module này.
// Trả trạng thái hiện tại để kiểm tra; ý nghĩa từng bộ đếm thuộc phạm vi module này.
