  put(W.KVPV_V873?.config,'scanMs',1200,'Linh Lung Tower');
// [VI dòng gốc 9002] gọi put(W.KVPV_V8?.config, 'scanMs', 8000, 'V8 coverage scan')
  put(W.KVPV_V8?.config,'scanMs',8000,'V8 coverage scan');
