  const job=W.KVPV_DAILY?.quickState?.();
// [VI dòng gốc 9019] Kiểm tra job?.running===true&&job?.job==='rảnh': đúng thì chạy nhánh sau if, sai thì chạy nhánh else.
  if(job?.running===true&&job?.job==='rảnh'){
// [VI dòng gốc 9020] Bắt đầu khối try; lỗi phát sinh sẽ được xử lý ở catch hoặc chuyển ra ngoài. | gọi W.KVPV_DAILY.stop() để dừng bộ điều khiển và dọn tài nguyên | gọi W.KVPV_DAILY.start() để khởi động bộ điều khiển
    try{W.KVPV_DAILY.stop();W.KVPV_DAILY.start();}
// [VI dòng gốc 9021] Nhận lỗi bằng e và chạy phần xử lý lỗi. | gọi S.notes.push('Auto Daily: '+String(e)) để thêm phần tử vào cuối mảng
    catch(e){S.notes.push('Auto Daily: '+String(e));}
// [VI dòng gốc 9022] Kiểm tra job?.running: đúng thì chạy nhánh sau if. | gọi S.notes.push('Auto Daily dang ban: tickMs moi se dung sau lan khoi dong ke tiep') để thêm phần tử vào cuối mảng
  }else if(job?.running){S.notes.push('Auto Daily dang ban: tickMs moi se dung sau lan khoi dong ke tiep');}
