    if (S.chargedConsumed) {S.lastReason='already attempted during this charge';return;}
// [VI dòng gốc 10642] Kiểm tra !p.nativeReady: đúng thì chạy nhánh sau if. | gán S.lastReason bằng 'native Transforming unavailable' | Kết thúc hàm hiện tại mà không trả giá trị cụ thể.
    if (!p.nativeReady) {S.lastReason='native Transforming unavailable';return;}
// [VI dòng gốc 10643] Kiểm tra p.nativeSending: đúng thì chạy nhánh sau if. | gán S.lastReason bằng 'native request already in flight' | Kết thúc hàm hiện tại mà không trả giá trị cụ thể.
    if (p.nativeSending) {S.lastReason='native request already in flight';return;}
// [VI dòng gốc 10644] Kiểm tra p.dead: đúng thì chạy nhánh sau if. | gán S.lastReason bằng 'character dead' | Kết thúc hàm hiện tại mà không trả giá trị cụ thể.
    if (p.dead) {S.lastReason='character dead';return;}
// [VI dòng gốc 10645] Kiểm tra C.requireAutoRunning && !p.autoRunning: đúng thì chạy nhánh sau if. | gán S.lastReason bằng 'auto paused' | Kết thúc hàm hiện tại mà không trả giá trị cụ thể.
    if (C.requireAutoRunning && !p.autoRunning) {S.lastReason='auto paused';return;}
// [VI dòng gốc 10646] Kiểm tra C.combatOnly && !p.inCombat: đúng thì chạy nhánh sau if. | gán S.lastReason bằng 'not in combat' | Kết thúc hàm hiện tại mà không trả giá trị cụ thể.
    if (C.combatOnly && !p.inCombat) {S.lastReason='not in combat';return;}
