    const m=_Ba?._eW?._pEt?.inst,rpc=_Ba?._eW?._dEt?.inst,
// [VI dòng gốc 13516] Tiếp tục hàm forgeInfo; thành phần cú pháp bắt đầu bằng name. Đọc cùng dòng mở phía trên: parts=_Ba?._rJ?._O$?.ins?.equipsDic?.keys;
      parts=_Ba?._rJ?._O$?.ins?.equipsDic?.keys;
