    if(typeof rpc?.ZhOperOneKey!=='function'||!Array.isArray(m?.zhList)||
// [VI dòng gốc 13518] Kết thúc hàm hiện tại và trả về: null.
       !Array.isArray(parts)||typeof m?.getCanUpZH!=='function')return null;
