        if(isGear&&typeof m.getPlayerIsChuanDai==='function'&&
// [VI dòng gốc 13583] gán safe bằng false | Thoát vòng lặp/switch hiện tại.
          m.getPlayerIsChuanDai(itemId)){safe=false;break;}
