    function next9022(at){
// [VI dòng gốc 14114] Kiểm tra last9022===null||intervals.length<2||!Number.isFinite(at): đúng thì chạy nhánh sau if. | Kết thúc hàm hiện tại và trả về: null.
      if(last9022===null||intervals.length<2||!Number.isFinite(at))return null;
// [VI dòng gốc 14115] Khai báo biến không gán lại bằng const: period = tính biểu thức intervals.reduce((sum,x)=>sum+x,0)/intervals.length
      const period=intervals.reduce((sum,x)=>sum+x,0)/intervals.length;
// [VI dòng gốc 14116] Khai báo biến không gán lại bằng const: maxDeviation = gọi Math.max(...intervals.map(x=>Math.abs(x-period)))
      const maxDeviation=Math.max(...intervals.map(x=>Math.abs(x-period)));
// [VI dòng gốc 14117] Kiểm tra maxDeviation>period*0.25: đúng thì chạy nhánh sau if. | Kết thúc hàm hiện tại và trả về: null.
      if(maxDeviation>period*0.25)return null; // unstable cycle; do not predict
// [VI dòng gốc 14118] Khai báo biến không gán lại bằng const: elapsed = tính biểu thức at-last9022
      const elapsed=at-last9022;
// [VI dòng gốc 14119] Kiểm tra elapsed<0||elapsed>period+350: đúng thì chạy nhánh sau if. | Kết thúc hàm hiện tại và trả về: null.
      if(elapsed<0||elapsed>period+350)return null; // stale observation
// [VI dòng gốc 14120] Kết thúc hàm hiện tại và trả về: gọi Math.max(0, period-elapsed).
      return Math.max(0,period-elapsed);
// [VI dòng gốc 14121] Đóng khối/hàm/mảng/lời gọi đã mở; dấu phẩy hoặc chấm phẩy kết thúc phần tương ứng.
    }
// [VI dòng gốc 14122] Định nghĩa hàm riskHp; tham số: at
    function riskHp(at){
// [VI dòng gốc 14123] Khai báo biến không gán lại bằng const: hit = gọi strongest(at)
      const hit=strongest(at);
// [VI dòng gốc 14124] Kết thúc hàm hiện tại và trả về: nếu c.bossSurvival===false thì lấy c.resumeFightPct, ngược lại lấy Math.max(c.resumeFightPct,Math.min(c.maxAdaptiveResumePct,hit+c.damageBufferPct)).
      return c.bossSurvival===false ? c.resumeFightPct :
// [VI dòng gốc 14125] gọi Math.max(c.resumeFightPct, Math.min(c.maxAdaptiveResumePct,hit+c.damageBufferPct)) | gọi Math.min(c.maxAdaptiveResumePct, hit+c.damageBufferPct)
        Math.max(c.resumeFightPct,Math.min(c.maxAdaptiveResumePct,hit+c.damageBufferPct));
// [VI dòng gốc 14126] Đóng khối/hàm/mảng/lời gọi đã mở; dấu phẩy hoặc chấm phẩy kết thúc phần tương ứng.
    }
