    if(!recent||recent.id!==id)return false;
// [VI dòng gốc 14987] Khai báo biến không gán lại bằng const: delay = tính biểu thức at-recent.at
    const delay=at-recent.at;
// [VI dòng gốc 14988] Kiểm tra delay<TQCASTCFG.minCastToImpactMs||delay>TQCASTCFG.maxCastToImpactMs: đúng thì chạy nhánh sau if. | Kết thúc hàm hiện tại và trả về: false.
    if(delay<TQCASTCFG.minCastToImpactMs||delay>TQCASTCFG.maxCastToImpactMs)return false;
