// [VI dòng gốc 15064] Khai báo biến không gán lại bằng const: times = tạo mảng gồm 0 vị trí: []
  const times=[];
// [VI dòng gốc 15065] Khai báo biến không gán lại bằng const: finite = tạo hàm với tham số n; mỗi lần gọi trả về gọi Number.isFinite(n)
  const finite=n=>Number.isFinite(n);
// [VI dòng gốc 15066] Khai báo biến không gán lại bằng const: median = tạo hàm với tham số nums
  const median=nums=>{
// [VI dòng gốc 15067] Kiểm tra !nums.length: đúng thì chạy nhánh sau if. | Kết thúc hàm hiện tại và trả về: null.
    if(!nums.length)return null;
// [VI dòng gốc 15068] Khai báo biến không gán lại bằng const: x = gọi [...nums].sort((a,b)=>a-b) để sắp xếp mảng tại chỗ; h = gọi Math.floor(x.length/2)
    const x=[...nums].sort((a,b)=>a-b),h=Math.floor(x.length/2);
// [VI dòng gốc 15069] Kết thúc hàm hiện tại và trả về: nếu x.length%2 thì lấy x[h], ngược lại lấy (x[h-1]+x[h])/2.
    return x.length%2?x[h]:(x[h-1]+x[h])/2;
// [VI dòng gốc 15070] Đóng khối/hàm/mảng/lời gọi đã mở; dấu phẩy hoặc chấm phẩy kết thúc phần tương ứng.
  };
// [VI dòng gốc 15071] Định nghĩa hàm limited; tham số: a, item, max | gọi a.push(item) để thêm phần tử vào cuối mảng | Kiểm tra a.length>max: đúng thì chạy nhánh sau if. | gọi a.shift()
  function limited(a,item,max){a.push(item);if(a.length>max)a.shift();}
// [VI dòng gốc 15072] Định nghĩa hàm detach; tham số: không có
  function detach(){
// [VI dòng gốc 15073] Kiểm tra role && typeof role.off==='function': đúng thì chạy nhánh sau if.
    if(role && typeof role.off==='function'){
// [VI dòng gốc 15074] Bắt đầu khối try; lỗi phát sinh sẽ được xử lý ở catch hoặc chuyển ra ngoài. | gọi role.off(1039, owner126, onCast) | Nhận lỗi bằng e và chạy phần xử lý lỗi. | gán lastError bằng 'off 1039: '+String(e)
      try{role.off(1039,owner126,onCast);}catch(e){lastError='off 1039: '+String(e);}
// [VI dòng gốc 15075] Đóng khối/hàm/mảng/lời gọi đã mở; dấu phẩy hoặc chấm phẩy kết thúc phần tương ứng.
    }
// [VI dòng gốc 15076] gán role bằng null | gán active bằng false
    role=null;active=false;
// [VI dòng gốc 15077] Đóng khối/hàm/mảng/lời gọi đã mở; dấu phẩy hoặc chấm phẩy kết thúc phần tương ứng.
  }
// [VI dòng gốc 15078] Định nghĩa hàm cleanForJSON; tham số: x | Kết thúc hàm hiện tại và trả về: gọi JSON.parse(JSON.stringify(x)) để phân tích dữ liệu đầu vào theo API đang gọi.
  function cleanForJSON(x){return JSON.parse(JSON.stringify(x));}
// [VI dòng gốc 15079] Định nghĩa hàm summarize; tham số: không có
  function summarize(){
// [VI dòng gốc 15080] Khai báo biến không gán lại bằng const: groups = tạo đối tượng gồm
    const groups={};
// [VI dòng gốc 15081] Duyệt từng giá trị trong session?.pairs||[] bằng const row. | Khai báo biến không gán lại bằng const: row (chưa gán giá trị)
    for(const row of session?.pairs||[]){
// [VI dòng gốc 15082] Khai báo biến không gán lại bằng const: k = gọi String(row.skillId) để chuyển sang chuỗi | gọi (groups[k]??=[]).push(row.castToHitMs) để thêm phần tử vào cuối mảng
      const k=String(row.skillId);(groups[k]??=[]).push(row.castToHitMs);
// [VI dòng gốc 15083] Đóng khối/hàm/mảng/lời gọi đã mở; dấu phẩy hoặc chấm phẩy kết thúc phần tương ứng.
    }
// [VI dòng gốc 15084] Kết thúc hàm hiện tại và trả về: gọi Object.entries(groups).map(([skillId,delays])=>{ const med=median(delays),maxDeviation=Math.max(...delays.map(x=>Math.abs(x-med))); return {skillId:+skillId,pairs:delays.length,med…((a,b)=>b.pairs-a.pairs) để sắp xếp mảng tại chỗ.
    return Object.entries(groups).map(([skillId,delays])=>{
// [VI dòng gốc 15085] Khai báo biến không gán lại bằng const: med = gọi median(delays); maxDeviation = gọi Math.max(...delays.map(x=>Math.abs(x-med)))
      const med=median(delays),maxDeviation=Math.max(...delays.map(x=>Math.abs(x-med)));
// [VI dòng gốc 15086] Kết thúc hàm hiện tại và trả về: tạo đối tượng gồm skillId, pairs, medianCastToHitMs, maxDeviationMs, validatedTiming.
      return {skillId:+skillId,pairs:delays.length,medianCastToHitMs:med,
// [VI dòng gốc 15087] Thuộc tính maxDeviationMs: maxDeviation | Thuộc tính validatedTiming: delays.length>=3 và chỉ đánh giá vế phải khi vế trái truthy: maxDeviation<=350
        maxDeviationMs:maxDeviation,validatedTiming:delays.length>=3&&maxDeviation<=350};
// [VI dòng gốc 15088] Định nghĩa hàm hàm không đặt tên; tham số: a, b
    }).sort((a,b)=>b.pairs-a.pairs);
// [VI dòng gốc 15089] Đóng khối/hàm/mảng/lời gọi đã mở; dấu phẩy hoặc chấm phẩy kết thúc phần tương ứng.
  }
// [VI dòng gốc 15090] Định nghĩa hàm onCast; tham số: targetId, skillId
  function onCast(targetId,skillId){
// [VI dòng gốc 15091] Kiểm tra !active||!S.running||String(S.bossId)!==bossId: đúng thì chạy nhánh sau if. | Kết thúc hàm hiện tại mà không trả giá trị cụ thể.
    if(!active||!S.running||String(S.bossId)!==bossId)return;
// [VI dòng gốc 15092] Khai báo biến không gán lại bằng const: id = gọi Number(skillId) để chuyển sang số; at = gọi clock()
    const id=Number(skillId),at=clock();
// [VI dòng gốc 15093] Kiểm tra !Number.isSafeInteger(id)||id<=0||id>1000000: đúng thì chạy nhánh sau if. | Kết thúc hàm hiện tại mà không trả giá trị cụ thể.
    if(!Number.isSafeInteger(id)||id<=0||id>1000000)return;
// [VI dòng gốc 15094] Khai báo biến không gán lại bằng const: last = đọc session.casts[session.casts.length-1]
    const last=session.casts[session.casts.length-1];
// [VI dòng gốc 15095] Kiểm tra last && last.skillId===id && at-last.at<V126CFG.castDedupMs: đúng thì chạy nhánh sau if. | tăng counts.duplicate một đơn vị sau khi lấy giá trị | Kết thúc hàm hiện tại mà không trả giá trị cụ thể.
    if(last && last.skillId===id && at-last.at<V126CFG.castDedupMs){counts.duplicate++;return;}
// [VI dòng gốc 15096] Khai báo biến không gán lại bằng const: targeted = tính biểu thức String(targetId)===actor
    const targeted=String(targetId)===actor;
// [VI dòng gốc 15097] gọi limited(session.casts, {at,skillId:id,targetId:String(targetId??''),targetsPlayer:targeted, basis:'native Boss role event 1039; …)
    limited(session.casts,{at,skillId:id,targetId:String(targetId??''),targetsPlayer:targeted,
// [VI dòng gốc 15098] Thuộc tính basis: "native Boss role event 1039; client visual/action signal"
      basis:'native Boss role event 1039; client visual/action signal'},V126CFG.maxEvents);
// [VI dòng gốc 15099] tăng counts.cast một đơn vị sau khi lấy giá trị
    counts.cast++;
// [VI dòng gốc 15100] Đóng khối/hàm/mảng/lời gọi đã mở; dấu phẩy hoặc chấm phẩy kết thúc phần tương ứng.
  }
// [VI dòng gốc 15101] Định nghĩa hàm onHit; tham số: marker, at, damage, flags
  function onHit(marker,at,damage,flags){
// [VI dòng gốc 15102] Kiểm tra !active||!S.running||String(S.bossId)!==bossId: đúng thì chạy nhánh sau if. | Kết thúc hàm hiện tại mà không trả giá trị cụ thể.
    if(!active||!S.running||String(S.bossId)!==bossId)return;
// [VI dòng gốc 15103] Khai báo biến không gán lại bằng const: m = gọi Number(marker) để chuyển sang số; d = gọi Number(damage) để chuyển sang số; f = gọi Number(flags) để chuyển sang số
    const m=Number(marker),d=Number(damage),f=Number(flags);
// [VI dòng gốc 15104] Kiểm tra !Number.isSafeInteger(m)||m<=0||m%10000!==0||!finite(at)|| !finite(d)||d<=0 || (f&32) || (f&256): đúng thì chạy nhánh sau if.
    if(!Number.isSafeInteger(m)||m<=0||m%10000!==0||!finite(at)||
// [VI dòng gốc 15105] Kết thúc hàm hiện tại mà không trả giá trị cụ thể.
       !finite(d)||d<=0 || (f&32) || (f&256))return;
// [VI dòng gốc 15106] Khai báo biến không gán lại bằng const: skillId = tính biểu thức m/10000
    const skillId=m/10000;
// [VI dòng gốc 15107] Kiểm tra previousHit&&previousHit.skillId===skillId&&at-previousHit.at<V126CFG.hitDedupMs: đúng thì chạy nhánh sau if.
    if(previousHit&&previousHit.skillId===skillId&&at-previousHit.at<V126CFG.hitDedupMs){
// [VI dòng gốc 15108] tăng counts.duplicate một đơn vị sau khi lấy giá trị | Kết thúc hàm hiện tại mà không trả giá trị cụ thể.
      counts.duplicate++;return;
// [VI dòng gốc 15109] Đóng khối/hàm/mảng/lời gọi đã mở; dấu phẩy hoặc chấm phẩy kết thúc phần tương ứng.
    }
// [VI dòng gốc 15110] gán previousHit bằng {skillId,at} | tăng counts.hit một đơn vị sau khi lấy giá trị
    previousHit={skillId,at};counts.hit++;
// [VI dòng gốc 15111] Khai báo biến có thể gán lại bằng let: paired = null
    let paired=null;
// [VI dòng gốc 15112] Lặp for: khởi tạo let i=session.casts.length-1; tiếp tục khi i>=0; sau mỗi vòng i--. | Khai báo biến có thể gán lại bằng let: i = tính biểu thức session.casts.length-1
    for(let i=session.casts.length-1;i>=0;i--){
// [VI dòng gốc 15113] Khai báo biến không gán lại bằng const: c = đọc session.casts[i]; lag = tính biểu thức at-c.at
      const c=session.casts[i],lag=at-c.at;
// [VI dòng gốc 15114] Kiểm tra lag>V126CFG.maxCastLagMs: đúng thì chạy nhánh sau if. | Thoát vòng lặp/switch hiện tại.
      if(lag>V126CFG.maxCastLagMs)break;
// [VI dòng gốc 15115] Kiểm tra c.skillId!==skillId||c.matched||lag<V126CFG.minCastLagMs: đúng thì chạy nhánh sau if. | Bỏ phần còn lại của vòng hiện tại và chuyển sang vòng tiếp theo.
      if(c.skillId!==skillId||c.matched||lag<V126CFG.minCastLagMs)continue;
// [VI dòng gốc 15116] Kiểm tra !(c.targetsPlayer||c.targetId==='0'||c.targetId===''): đúng thì chạy nhánh sau if. | Bỏ phần còn lại của vòng hiện tại và chuyển sang vòng tiếp theo.
      if(!(c.targetsPlayer||c.targetId==='0'||c.targetId===''))continue;
// [VI dòng gốc 15117] gán c.matched bằng true | gán paired bằng {at,skillId,castToHitMs:Math.round(lag),damage:d,flags:f}
      c.matched=true;paired={at,skillId,castToHitMs:Math.round(lag),damage:d,flags:f};
// [VI dòng gốc 15118] gọi limited(session.pairs, paired, V126CFG.maxEvents)
      limited(session.pairs,paired,V126CFG.maxEvents);
// [VI dòng gốc 15119] tăng counts.pairs một đơn vị sau khi lấy giá trị | Thoát vòng lặp/switch hiện tại.
      counts.pairs++;break;
// [VI dòng gốc 15120] Đóng khối/hàm/mảng/lời gọi đã mở; dấu phẩy hoặc chấm phẩy kết thúc phần tương ứng.
    }
// [VI dòng gốc 15121] Kiểm tra !paired: đúng thì chạy nhánh sau if. | tăng counts.unpaired một đơn vị sau khi lấy giá trị
    if(!paired)counts.unpaired++;
// [VI dòng gốc 15122] gọi limited(session.hits, {at,skillId,damage:d,flags:f,castMatched:!!paired}, V126CFG.maxEvents)
    limited(session.hits,{at,skillId,damage:d,flags:f,castMatched:!!paired},V126CFG.maxEvents);
// [VI dòng gốc 15123] Kiểm tra skillId===9005: đúng thì chạy nhánh sau if, sai thì chạy nhánh else. | gán last9005 bằng at
    if(skillId===9005){last9005=at;}
// [VI dòng gốc 15124] Kiểm tra skillId===8011&&last9005!==null: đúng thì chạy nhánh sau if.
    else if(skillId===8011&&last9005!==null){
// [VI dòng gốc 15125] Khai báo biến không gán lại bằng const: delay = tính biểu thức at-last9005
      const delay=at-last9005;
// [VI dòng gốc 15126] Kiểm tra delay>=V126CFG.chainMinMs&&delay<=V126CFG.chainMaxMs: đúng thì chạy nhánh sau if.
      if(delay>=V126CFG.chainMinMs&&delay<=V126CFG.chainMaxMs){
// [VI dòng gốc 15127] gọi limited(times, Math.round(delay), 30) | tăng counts.chain một đơn vị sau khi lấy giá trị
        limited(times,Math.round(delay),30);counts.chain++;
// [VI dòng gốc 15128] gọi limited(session.chains, {fromSkill:9005,toSkill:8011,impactGapMs:Math.round(delay),at}, V126CFG.maxEvents)
        limited(session.chains,{fromSkill:9005,toSkill:8011,impactGapMs:Math.round(delay),at},V126CFG.maxEvents);
// [VI dòng gốc 15129] Đóng khối/hàm/mảng/lời gọi đã mở; dấu phẩy hoặc chấm phẩy kết thúc phần tương ứng.
      }
// [VI dòng gốc 15130] gán last9005 bằng null
      last9005=null;
// [VI dòng gốc 15131] Đóng khối/hàm/mảng/lời gọi đã mở; dấu phẩy hoặc chấm phẩy kết thúc phần tương ứng.
    }
// [VI dòng gốc 15132] Đóng khối/hàm/mảng/lời gọi đã mở; dấu phẩy hoặc chấm phẩy kết thúc phần tương ứng.
  }
// [VI dòng gốc 15133] Chú thích gốc của tác giả; không được thực thi. Nội dung: Bật bộ điều khiển và lịch kiểm tra của module; trả trạng thái sau khi khởi động.
  // Bật bộ điều khiển và lịch kiểm tra của module; trả trạng thái sau khi khởi động.
// [VI dòng gốc 15134] Định nghĩa hàm start; tham số: boss. Mục đích: khởi động bộ điều khiển
  function start(boss){
// [VI dòng gốc 15135] gọi detach() | gán bossId bằng '' | gán bossOcc bằng null | gán stage bằng null
    detach();bossId='';bossOcc=null;stage=null;previousHit=null;last9005=null;times.length=0;
// [VI dòng gốc 15136] Duyệt từng giá trị trong Object.keys(counts) bằng const k. | Khai báo biến không gán lại bằng const: k (chưa gán giá trị) | gán counts[k] bằng 0
    for(const k of Object.keys(counts))counts[k]=0;
// [VI dòng gốc 15137] gán session bằng null | gán lastError bằng ''
    session=null;lastError='';
// [VI dòng gốc 15138] Kiểm tra !V126CFG.enabled: đúng thì chạy nhánh sau if. | Kết thúc hàm hiện tại và trả về: false.
    if(!V126CFG.enabled)return false;
// [VI dòng gốc 15139] Kiểm tra !boss||typeof boss.on!=='function'||typeof boss.off!=='function': đúng thì chạy nhánh sau if.
    if(!boss||typeof boss.on!=='function'||typeof boss.off!=='function'){
// [VI dòng gốc 15140] gán lastError bằng 'Selected Boss does not support on/off events' | Kết thúc hàm hiện tại và trả về: false.
      lastError='Selected Boss does not support on/off events';return false;
// [VI dòng gốc 15141] Đóng khối/hàm/mảng/lời gọi đã mở; dấu phẩy hoặc chấm phẩy kết thúc phần tương ứng.
    }
// [VI dòng gốc 15142] gán bossId bằng oid(boss) | gán bossOcc bằng Number(prop(boss,'occ'))||null
    bossId=oid(boss);bossOcc=Number(prop(boss,'occ'))||null;
// [VI dòng gốc 15143] Bắt đầu khối try; lỗi phát sinh sẽ được xử lý ở catch hoặc chuyển ra ngoài. | gán stage bằng Number(_Ba?._Co?._Mo?.ins?.curLv)||null | Nhận lỗi bằng _ và chạy phần xử lý lỗi. | gán stage bằng null
    try{stage=Number(_Ba?._Co?._Mo?.ins?.curLv)||null;}catch(_){stage=null;}
// [VI dòng gốc 15144] gán session bằng {bossId,bossOcc,stage,startedAt:new Date().toISOString(), client:'V12.6 observational instrumentation',casts:[],hits:[],pairs:[],chains:[]}
    session={bossId,bossOcc,stage,startedAt:new Date().toISOString(),
// [VI dòng gốc 15145] Thuộc tính client: "V12.6 observational instrumentation" | Thuộc tính casts: tạo mảng gồm 0 vị trí: [] | Thuộc tính hits: tạo mảng gồm 0 vị trí: [] | Thuộc tính pairs: tạo mảng gồm 0 vị trí: []
      client:'V12.6 observational instrumentation',casts:[],hits:[],pairs:[],chains:[]};
// [VI dòng gốc 15146] gọi limited(sessions, session, V126CFG.maxSessions)
    limited(sessions,session,V126CFG.maxSessions);
// [VI dòng gốc 15147] Bắt đầu khối try; lỗi phát sinh sẽ được xử lý ở catch hoặc chuyển ra ngoài. | gọi boss.on(1039, owner126, onCast) | gán role bằng boss | gán active bằng true
    try{boss.on(1039,owner126,onCast);role=boss;active=true;return true;}
// [VI dòng gốc 15148] Nhận lỗi bằng e và chạy phần xử lý lỗi. | gán lastError bằng 'on 1039: '+String(e) | gọi detach() | Kết thúc hàm hiện tại và trả về: false.
    catch(e){lastError='on 1039: '+String(e);detach();return false;}
// [VI dòng gốc 15149] Đóng khối/hàm/mảng/lời gọi đã mở; dấu phẩy hoặc chấm phẩy kết thúc phần tương ứng.
  }
// [VI dòng gốc 15150] Chú thích gốc của tác giả; không được thực thi. Nội dung: Dừng bộ điều khiển, hủy lịch và giải phóng tài nguyên do module này sở hữu.
  // Dừng bộ điều khiển, hủy lịch và giải phóng tài nguyên do module này sở hữu.
// [VI dòng gốc 15151] Định nghĩa hàm stop; tham số: không có. Mục đích: dừng bộ điều khiển và dọn tài nguyên | gọi detach() | Kiểm tra session&&!session.endedAt: đúng thì chạy nhánh sau if. | gán session.endedAt bằng new Date().toISOString()
  function stop(){detach();if(session&&!session.endedAt)session.endedAt=new Date().toISOString();}
// [VI dòng gốc 15152] Chú thích gốc của tác giả; không được thực thi. Nội dung: Trả trạng thái hiện tại để kiểm tra; ý nghĩa từng bộ đếm thuộc phạm vi module này.
  // Trả trạng thái hiện tại để kiểm tra; ý nghĩa từng bộ đếm thuộc phạm vi module này.
