  minIntervals:3,maxJitterMs:260,leadMs:880,afterMs:320,
// [VI dòng gốc 16112] Thuộc tính reflectWindowMs: 170 | Thuộc tính reflectMinRatio: 5.8 | Thuộc tính reflectMaxRatio: 7.55
  reflectWindowMs:170,reflectMinRatio:5.80,reflectMaxRatio:7.55,
// [VI dòng gốc 16113] Thuộc tính classifierWaitMs: 200 | Thuộc tính outgoingKeepMs: 2500 | Thuộc tính maxEvidence: 48
