    if(s.owner==='combat'&&s.hitrunRunning!==true)
// [VI dòng gốc 17460] gọi add('combat-lease', 'info', 'Scene lease may be temporary; core will expire naturally.')
      add('combat-lease','info','Scene lease may be temporary; core will expire naturally.');
// [VI dòng gốc 17461] Kiểm tra s.phase==='RETREAT'&&s.hitrunRunning===true && s.retreatTooLong===true: đúng thì chạy nhánh sau if.
    if(s.phase==='RETREAT'&&s.hitrunRunning===true && s.retreatTooLong===true)
// [VI dòng gốc 17462] gọi add('retreat-review', 'warn', 'HitRun retreat unusually long; do not force scene change.')
      add('retreat-review','warn','HitRun retreat unusually long; do not force scene change.');
