  const state={observations:0,repairs:0,failures:0,lastActionAt:0,
// [VI dòng gốc 17483] Thuộc tính attemptedAt: tạo mảng gồm 0 vị trí: [] | Thuộc tính issues: tạo mảng gồm 0 vị trí: [] | Thuộc tính history: tạo mảng gồm 0 vị trí: [] | Thuộc tính lastError: ""
    attemptedAt:[],issues:[],history:[],lastError:'',lastOutcome:'idle'};
