  const blocked=(reason,decision=null)=>({version:VERSION,permitted:false,
// [VI dòng gốc 17724] Thuộc tính action: null | Thuộc tính reason: dùng biến cùng tên | Thuộc tính decisionId: decision | Thuộc tính gameplayMutation: false
    action:null,reason,decisionId:decision,gameplayMutation:false});
