// [VI dòng gốc 19310] Định nghĩa hàm syncRoomEpoch; tham số: không có
  function syncRoomEpoch(){
// [VI dòng gốc 19311] Khai báo biến không gán lại bằng const: inRoom = gọi meInTeam(); id = gọi Number(roomId()) để chuyển sang số
    const inRoom=meInTeam(),id=Number(roomId());
// [VI dòng gốc 19312] Khai báo biến không gán lại bằng const: key = nếu inRoom&&Number.isSafeInteger(id)&&id>=0 thì lấy String(id), ngược lại lấy null
    const key=inRoom&&Number.isSafeInteger(id)&&id>=0?String(id):null;
// [VI dòng gốc 19313] Kiểm tra key===S.roomEpoch: đúng thì chạy nhánh sau if. | Kết thúc hàm hiện tại mà không trả giá trị cụ thể.
    if(key===S.roomEpoch)return;
// [VI dòng gốc 19314] Kiểm tra key===null: đúng thì chạy nhánh sau if.
    if(key===null){
// [VI dòng gốc 19315] Kiểm tra S.roomEpoch!==null: đúng thì chạy nhánh sau if.
      if(S.roomEpoch!==null){
// [VI dòng gốc 19316] gán S.leftRoomEpoch bằng S.roomEpoch | gán S.roomEpoch bằng null
        S.leftRoomEpoch=S.roomEpoch;S.roomEpoch=null;
// [VI dòng gốc 19317] gọi audit('progress', 'Đã rời phòng '+S.leftRoomEpoch+'; không tự mời/xin vào phòng cũ')
        audit('progress','Đã rời phòng '+S.leftRoomEpoch+'; không tự mời/xin vào phòng cũ');
// [VI dòng gốc 19318] Đóng khối/hàm/mảng/lời gọi đã mở; dấu phẩy hoặc chấm phẩy kết thúc phần tương ứng.
      }
// [VI dòng gốc 19319] Kết thúc hàm hiện tại mà không trả giá trị cụ thể.
      return;
// [VI dòng gốc 19320] Đóng khối/hàm/mảng/lời gọi đã mở; dấu phẩy hoặc chấm phẩy kết thúc phần tương ứng.
    }
// [VI dòng gốc 19321] Chú thích gốc của tác giả; không được thực thi. Nội dung: Initial room and each confirmed new room get independent, bounded invite budgets.
    // Initial room and each confirmed new room get independent, bounded invite budgets.
// [VI dòng gốc 19322] Khai báo biến không gán lại bằng const: prev = S.roomEpoch hoặc dùng vế phải khi vế trái là null/undefined: S.leftRoomEpoch
    const prev=S.roomEpoch??S.leftRoomEpoch;
// [VI dòng gốc 19323] gán S.roomEpoch bằng key | gán S.leftRoomEpoch bằng null | tăng S.roomChanges một đơn vị sau khi lấy giá trị
    S.roomEpoch=key;S.leftRoomEpoch=null;S.roomChanges++;
// [VI dòng gốc 19324] gán S.inviteCount bằng 0 | gán S.approveCount bằng 0 | gán S.lastInviteAt bằng 0
    S.inviteCount=0;S.approveCount=0;S.lastInviteAt=0;
// [VI dòng gốc 19325] gán S.publicInviteCount bằng 0 | gán S.lastPublicInviteAt bằng 0 | gán S.publicRoomId bằng null
    S.publicInviteCount=0;S.lastPublicInviteAt=0;S.publicRoomId=null;
// [VI dòng gốc 19326] gán S.readyKey bằng null | gán S.readySince bằng 0 | gán S.nativeAutoAt bằng 0
    S.readyKey=null;S.readySince=0;S.nativeAutoAt=0;
// [VI dòng gốc 19327] gán S.startKey bằng null | gán S.startSentAt bằng 0
    S.startKey=null;S.startSentAt=0;
// [VI dòng gốc 19328] Kiểm tra role()==='clone': đúng thì chạy nhánh sau if. | gán S.acceptCount bằng 0 | gán S.joinCount bằng 0 | gán S.joinTargetRoom bằng key
    if(role()==='clone'){S.acceptCount=0;S.joinCount=0;S.joinTargetRoom=key;}
// [VI dòng gốc 19329] gọi audit('progress', 'Đã xác nhận '+(prev&&prev!==key?'phòng mới '+key+' (trước '+prev+')':'phòng '+key)+', đặt lại giới hạn mời …)
    audit('progress','Đã xác nhận '+(prev&&prev!==key?'phòng mới '+key+' (trước '+prev+')':'phòng '+key)+', đặt lại giới hạn mời theo phòng');
// [VI dòng gốc 19330] Đóng khối/hàm/mảng/lời gọi đã mở; dấu phẩy hoặc chấm phẩy kết thúc phần tương ứng.
  }
// [VI dòng gốc 19331] Định nghĩa hàm nextCloneOpportunity; tham số: không có
  function nextCloneOpportunity(){
// [VI dòng gốc 19332] Kiểm tra role()!=='clone'||meInTeam(): đúng thì chạy nhánh sau if. | Kết thúc hàm hiện tại và trả về: null.
    if(role()!=='clone'||meInTeam())return null;
// [VI dòng gốc 19333] Bắt đầu khối try; lỗi phát sinh sẽ được xử lý ở catch hoặc chuyển ra ngoài.
    try{
// [VI dòng gốc 19334] Khai báo biến không gán lại bằng const: fid = đọc _Ba?._cm?.TeamTypeToFuncId?.[6] nếu đối tượng tồn tại (bỏ qua truy cập/gọi khi phần tùy chọn không tồn tại)
      const fid=_Ba?._cm?.TeamTypeToFuncId?.[6];
// [VI dòng gốc 19335] Khai báo biến không gán lại bằng const: asks = nếu typeof team()?.getAskLs==='function' thì lấy team().getAskLs(fid), ngược lại lấy []
      const asks=typeof team()?.getAskLs==='function'?team().getAskLs(fid):[];
// [VI dòng gốc 19336] Khai báo biến không gán lại bằng const: invited = nếu Array.isArray(asks) thì lấy asks.find(v=>Array.isArray(v)&& Number(v[1])===6&&String(v[5])===C.mainId&&Number(v[4])===C.tier), ngược lại lấy null
      const invited=Array.isArray(asks)?asks.find(v=>Array.isArray(v)&&
// [VI dòng gốc 19337] gọi Number(v[1]) để chuyển sang số | gọi String(v[5]) để chuyển sang chuỗi | gọi Number(v[4]) để chuyển sang số
        Number(v[1])===6&&String(v[5])===C.mainId&&Number(v[4])===C.tier):null;
// [VI dòng gốc 19338] Kiểm tra invited: đúng thì chạy nhánh sau if. | Kết thúc hàm hiện tại và trả về: gọi String(invited[2]) để chuyển sang chuỗi.
      if(invited)return String(invited[2]);
// [VI dòng gốc 19339] Khai báo biến không gán lại bằng const: list = đọc team()?.roomList nếu đối tượng tồn tại (bỏ qua truy cập/gọi khi phần tùy chọn không tồn tại)
      const list=team()?.roomList;
// [VI dòng gốc 19340] Khai báo biến không gán lại bằng const: room = nếu Array.isArray(list) thì lấy list.find(v=>Array.isArray(v)&&Number(v[2])===6&& String(v[9])===C.mainId&&Number(v[4])===C.tier&&Number(v[5])<4), ngược lại lấy null
      const room=Array.isArray(list)?list.find(v=>Array.isArray(v)&&Number(v[2])===6&&
// [VI dòng gốc 19341] gọi String(v[9]) để chuyển sang chuỗi | gọi Number(v[4]) để chuyển sang số | gọi Number(v[5]) để chuyển sang số
        String(v[9])===C.mainId&&Number(v[4])===C.tier&&Number(v[5])<4):null;
// [VI dòng gốc 19342] Kết thúc hàm hiện tại và trả về: nếu room thì lấy String(room[1]), ngược lại lấy null.
      return room?String(room[1]):null;
// [VI dòng gốc 19343] Nhận lỗi bằng _ và chạy phần xử lý lỗi. | Kết thúc hàm hiện tại và trả về: null.
    }catch(_){return null;}
// [VI dòng gốc 19344] Đóng khối/hàm/mảng/lời gọi đã mở; dấu phẩy hoặc chấm phẩy kết thúc phần tương ứng.
  }
