      createCount:S.createCount,joinCount:S.joinCount,
// [VI dòng gốc 19692] Thuộc tính inviteCount: đọc S.inviteCount | Thuộc tính acceptCount: đọc S.acceptCount | Thuộc tính approveCount: đọc S.approveCount
      inviteCount:S.inviteCount,acceptCount:S.acceptCount,approveCount:S.approveCount,
// [VI dòng gốc 19693] Thuộc tính roomChanges: đọc S.roomChanges | Thuộc tính observedRoom: đọc S.roomEpoch | Thuộc tính joinTargetRoom: đọc S.joinTargetRoom
      roomChanges:S.roomChanges,observedRoom:S.roomEpoch,joinTargetRoom:S.joinTargetRoom,
